public class Main{
 static long xsNext(long x){x^=x<<13;x^=x>>>7;x^=x<<17;return x;}
 public static void main(String[]a){ StringBuilder out=new StringBuilder(); long r=12345; for(int i=0;i<10000;i++){ r=xsNext(r); long id=Long.remainderUnsigned(r,100000); r=xsNext(r); int len=4+(int)Long.remainderUnsigned(r,9); StringBuilder name=new StringBuilder(); for(int j=0;j<len;j++){ r=xsNext(r); if(j%8==7) name.append(r%2==0?'\"':'\\'); else name.append((char)('a'+Long.remainderUnsigned(r,26))); } r=xsNext(r); long score=Long.remainderUnsigned(r,1000); boolean active=(r>>>8)%2==0; out.append("{\"id\":").append(id).append(",\"name\":\""); for(int k=0;k<name.length();k++){ char c=name.charAt(k); if(c=='\"'||c=='\\') out.append('\\'); out.append(c); } out.append("\",\"score\":").append(score).append(",\"active\":").append(active?"true":"false").append("},"); } long h=1469598103934665603L; for(int k=0;k<out.length();k++){ h=(h^(out.charAt(k)&0xFF))*1099511628211L; } System.out.println(out.length()); System.out.println(Long.toUnsignedString(h)); }
}